const alert = $json;
const escape = (value) => String(value ?? '').replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const evidence = Array.isArray(alert.evidence) ? alert.evidence : [];
const evidenceHtml = evidence.map((row) => `<li>${escape(row.type || 'Evidence')}: ${row.source_url ? `<a href="${escape(row.source_url)}">Open source</a>` : 'Source link unavailable'}</li>`).join('') || '<li>No structured evidence link supplied.</li>';
const search = encodeURIComponent(`"${alert.vendor_name || ''}" "${alert.company_number || ''}"`);
return { json: { ...alert, subject: `[${String(alert.severity || 'medium').toUpperCase()}] Review required — ${alert.vendor_name || 'Company'}`, html: `<h2>Company risk alert</h2><p><strong>Company:</strong> ${escape(alert.vendor_name)}<br><strong>Company number:</strong> ${escape(alert.company_number)}<br><strong>Severity:</strong> ${escape(alert.severity)}<br><strong>SLA due:</strong> ${escape(alert.sla_due_at || 'Not set')}</p><h3>Reason</h3><p>${escape(alert.reason || alert.title || 'Review required')}</p><h3>Evidence</h3><ul>${evidenceHtml}</ul><p><a href="https://news.google.com/rss/search?q=${search}&hl=en-GB&gl=GB&ceid=GB:en">Optional external-news search</a></p><p><em>News results may be inaccurate, incomplete, alleged or about another company. They are contextual only and must not be the sole basis for an adverse decision.</em></p>` } };

const vendors = $('Get monitored companies').all().map((item) => item.json);
const alerts = $('Get operational alerts').all().map((item) => item.json);
const health = $json;
const now = new Date();
const weekly = now.getDay() === 1;
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const open = alerts.filter((a) => !['resolved', 'false_positive'].includes(String(a.status || '').toLowerCase()));
const riskRows = vendors.filter((v) => v.recommend_manual_review || ['D','E','F'].includes(v.latest_grade)).slice(0, 25).map((v) => `<li>${esc(v.name)} (${esc(v.company_number)}) — score ${esc(v.latest_score ?? 'unavailable')} / ${esc(v.latest_grade ?? 'ungraded')}</li>`).join('') || '<li>No companies currently flagged in the register.</li>';
const alertRows = open.slice(0, 25).map((a) => `<li><strong>${esc(a.severity)}</strong> — ${esc(a.title || a.reason)} (${esc(a.vendor_name || `vendor ${a.vendor_id}`)})</li>`).join('') || '<li>No open operational alerts.</li>';
const weeklyText = weekly ? '<p>This is the weekly digest. Review unresolved alerts, reviewer decisions and stale-source items before the next reporting period.</p>' : '';
return { json: { subject: `${weekly ? 'Weekly' : 'Daily'} supplier-monitoring digest — ${now.toLocaleDateString('en-GB')}`, html: `<h2>${weekly ? 'Weekly' : 'Daily'} supplier-monitoring digest</h2><p><strong>Companies monitored:</strong> ${vendors.length}<br><strong>Open alerts:</strong> ${open.length}<br><strong>Failed notification count:</strong> ${esc(health.failed_notification_count ?? 0)}</p>${weeklyText}<h3>Review queue</h3><ul>${riskRows}</ul><h3>Open alerts</h3><ul>${alertRows}</ul><p><em>Scores are decision support. Verify material signals and source evidence before any business decision.</em></p>` } };

const form = $input.first();
const binaryFields = form.binary ?? {};

const binaryKey =
  Object.keys(binaryFields).find((key) => key === 'Company CSV') ??
  Object.keys(binaryFields)[0];

if (!binaryKey) {
  throw new Error('No CSV upload was received. Attach a CSV file before submitting the form.');
}

const file = binaryFields[binaryKey];
const fileName = String(file.fileName || '').toLowerCase();
const mimeType = String(file.mimeType || '').toLowerCase();

if (!fileName.endsWith('.csv') && !mimeType.includes('csv') && !mimeType.includes('text/plain')) {
  throw new Error(`Upload must be a CSV file. Received: ${file.fileName || binaryKey}`);
}

const csv = (await this.helpers.getBinaryDataBuffer(0, binaryKey))
  .toString('utf8')
  .replace(/^\uFEFF/, '');

const rows = csv.split(/\r?\n/).filter((row) => row.trim());

if (rows.length < 2) {
  throw new Error('CSV needs a header row and at least one company row.');
}

function parseRow(row) {
  const values = [];
  let value = '';
  let quoted = false;

  for (let i = 0; i < row.length; i += 1) {
    const char = row[i];

    if (char === '"') {
      if (quoted && row[i + 1] === '"') {
        value += '"';
        i += 1;
      } else {
        quoted = !quoted;
      }
    } else if (char === ',' && !quoted) {
      values.push(value.trim());
      value = '';
    } else {
      value += char;
    }
  }

  values.push(value.trim());
  return values;
}

const headers = parseRow(rows[0]).map((value) =>
  value.toLowerCase().replace(/[^a-z0-9]/g, '')
);

const companyNumberIndex = headers.findIndex((value) =>
  ['companynumber', 'companyno', 'registrationnumber'].includes(value)
);

const displayNameIndex = headers.findIndex((value) =>
  ['displayname', 'companyname', 'legalcompanyname', 'name'].includes(value)
);

if (companyNumberIndex === -1) {
  throw new Error('CSV must contain a Company Number column.');
}

const selectedCriticality = String(
  form.json['Default supplier criticality'] || 'Medium'
).trim();

const validCriticalities = new Set(['Low', 'Medium', 'High', 'Critical']);
const supplierCriticality = validCriticalities.has(selectedCriticality)
  ? selectedCriticality
  : 'Medium';

const seen = new Set();
const output = [];

for (let rowIndex = 1; rowIndex < rows.length; rowIndex += 1) {
  const values = parseRow(rows[rowIndex]);
  const companyNumber = String(values[companyNumberIndex] || '').trim().toUpperCase();

  if (!companyNumber || seen.has(companyNumber)) {
    continue;
  }

  seen.add(companyNumber);

  const displayName =
    displayNameIndex >= 0 ? String(values[displayNameIndex] || '').trim() : '';

  output.push({
    json: {
      company_number: companyNumber,
      ...(displayName ? { display_name: displayName } : {}),
      supplier_criticality: supplierCriticality,
      csv_row: rowIndex + 1,
      upload_file_name: file.fileName || null,
    },
  });
}

if (!output.length) {
  throw new Error('No usable company numbers were found in the CSV.');
}

return output;
